#[derive(Clone)]
struct PanelItem {
    label: String,
    description: String,
    value: PanelValue,
    checked: bool,
}

struct SelectorPanel {
    title: String,
    help: String,
    items: Vec<PanelItem>,
    selected: usize,
    query: String,
}

impl SelectorPanel {
    fn visible_indices(&self) -> Vec<usize> {
        self.items
            .iter()
            .enumerate()
            .filter(|(_, item)| {
                fuzzy_match(&item.label, &self.query) || fuzzy_match(&item.description, &self.query)
            })
            .map(|(index, _)| index)
            .collect()
    }

    fn selected_item(&self) -> Option<&PanelItem> {
        self.visible_indices()
            .get(self.selected)
            .and_then(|index| self.items.get(*index))
    }
}

